using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Verdant.Automation;
public static class VerdantClassicChecks
{
    static int checks;static List<string> names;static void Check(bool value,string name){if(!value)throw new Exception("FAIL: "+name);checks++;names.Add(name);}
    static ClassicFarm Sandbox(int size=4){var f=new ClassicFarm(7);f.Data.allowLockedSyntax=true;foreach(var t in ClassicFarm.Techs)f.Data.unlocks.Add(new Stock(t.id,t.max));f.Resize(size);foreach(string item in ClassicFarm.Items)f.Add(item,100000);return f;}
    static ClassicSession Execute(ClassicFarm f,string source,int frames=36000){var s=new ClassicSession(f);s.Start(source);while(s.Running&&frames-->0)s.FixedTick();if(s.Error!="")throw new Exception(s.Error);if(s.Running)throw new Exception("Task did not finish.");return s;}
    public static void Run()
    {
        checks=0;names=new List<string>();VerdantScriptChecks.Run();foreach(string example in ClassicExamples.Sources)new ScriptParser().Parse(example);Check(true,"All nine shipped programs compile");
        var f=new ClassicFarm();Check(f.Data.size==1&&f.Count("hay")==0,"Fresh start is one plot with no granted inventory");f.Advance(4);Check(f.Harvest(0,0)&&f.Count("hay")==1,"Initial grass provides a recovery economy");Check(!f.Unlock("expand"),"Research prerequisites cannot be bypassed");f.Add("hay",50);Check(f.Unlock("plant")&&f.Unlock("expand")&&f.Data.size==2,"Resource-funded research expands the farm");
        f=Sandbox();Execute(f,"till()\nplant(Entities.Carrot)\nwhile not can_harvest():\n    do_a_flip()\nharvest()");Check(f.Data.harvested.Any(x=>x.id=="carrot"&&x.amount>0),"Crop production through the real interpreter");
        f=Sandbox();foreach(var c in f.Data.cells){c.entity="pumpkin";c.growth=100;c.measure=1;c.ground="soil";}double initial=f.Count("pumpkin");Check(f.Harvest(1,1)&&f.Count("pumpkin")>initial+16&&f.Data.cells.All(c=>c.entity==""),"A complete square merges and harvests as one block");
        f=Sandbox(2);foreach(var c in f.Data.cells){c.entity="pumpkin";c.growth=100;c.measure=1;c.ground="soil";}f.Cell(0,0).entity="dead_pumpkin";f.Harvest(1,1);Check(f.Cell(0,0).entity=="dead_pumpkin"&&f.Data.cells.Count(c=>c.entity=="pumpkin")==2,"Dead pumpkins prevent the full square from merging");Check(f.Plant("pumpkin",0,0),"Planting replaces a dead pumpkin");
        f=Sandbox(2);int value=0;foreach(var c in f.Data.cells){c.entity="cactus";c.growth=2;c.measure=value++;c.ground="soil";}initial=f.Count("cactus");f.Harvest(0,0);Check(f.Count("cactus")-initial>=16&&f.Data.cells.All(c=>c.entity==""),"Two-dimensional sorted cacti chain harvest");
        f=Sandbox(2);value=4;foreach(var c in f.Data.cells){c.entity="cactus";c.growth=2;c.measure=value--;c.ground="soil";}f.Harvest(0,0);Check(f.Data.cells.Count(c=>c.entity=="cactus")==3,"Unsorted cacti do not chain harvest");
        f=Sandbox();foreach(var c in f.Data.cells){c.entity="sunflower";c.growth=100;c.measure=10;}f.Cell(0,0).measure=15;initial=f.Count("power");f.Harvest(0,0);Check(f.Count("power")-initial>=8,"Measuring the maximal sunflower earns a bonus");
        f=Sandbox();f.Cell(0,0).entity="carrot";f.Cell(0,0).growth=0;double before=f.Cell(0,0).growth;f.Use("fertilizer",0,0);Check(f.Cell(0,0).infected&&f.Cell(0,0).growth>=before+2,"Fertilizer accelerates growth and infects");f.Use("weird_substance",0,0);Check(!f.Cell(0,0).infected&&f.Cell(1,0).infected,"Treatment toggles the local neighborhood");
        f=Sandbox();f.Cell(0,0).entity="bush";Check(f.Use("weird_substance",0,0,1024)&&f.maze,"Special material creates a maze");var reached=new HashSet<int>{0};var q=new Queue<int>();q.Enqueue(0);while(q.Count>0){int a=q.Dequeue();for(int d=0;d<4;d++)if(f.CanMove(a,d)){int b=f.NeighborIndex(a,d,false);if(reached.Add(b))q.Enqueue(b);}}Check(reached.Count==16,"Generated maze has a connected traversable layout");initial=f.Count("gold");Check(f.Harvest(f.treasure%4,f.treasure/4)&&f.Count("gold")>initial&&!f.maze,"Treasure harvest pays resources and clears the maze");
        f=Sandbox();var session=Execute(f,"x=0\ndef worker(n):\n    global x\n    x=99\n    return n*2\nd=spawn_drone(worker,7)\nv=wait_for(d)\nprint(v)\nassertion=v==14 and x==0");Check(ScriptValue.Truth(session.drones[0].task.context.scope.values["assertion"]),"Independent drones return values and isolate globals");
        f=Sandbox();session=Execute(f,"def worker():\n    for i in range(4):\n        move(North)\na=spawn_drone(worker)\nb=spawn_drone(worker)\nwait_for(a)\nwait_for(b)");Check(session.TotalSpawned==3&&session.drones.All(d=>d.finished),"Independent workers can share a tile without collision");
        f=Sandbox();f.Data.programs.Add(new ClassicProgram("experiment","for i in range(3):\n    do_a_flip()"));double inventory=f.Count("carrot");session=Execute(f,"a=simulate('experiment', {}, {}, {}, 2, 64)\nb=simulate('experiment', {}, {}, {}, 2, 64)\nmatch=a==b");Check(ScriptValue.Truth(session.drones[0].task.context.scope.values["match"])&&f.Count("carrot")==inventory,"Fixed-seed simulations are reproducible and preserve real inventory");
        var one=new ClassicFarm(42);var two=new ClassicFarm(42);Check(one.Random()==two.Random()&&one.Random()==two.Random(),"Randomness is local and reproducible");
        f=Sandbox(4);int seedValue=0;foreach(var c in f.Data.cells){c.entity="cactus";c.ground="soil";c.growth=100;c.measure=(seedValue++*7+3)%10;}Execute(f,ClassicExamples.Sources[4]);Check(f.Data.cells.All(c=>c.entity!="cactus"),"The shipped sorting program orders and harvests a real field");
        foreach(int side in new[]{4,8}){f=Sandbox(side);f.Cell(0,0).entity="bush";f.Use("weird_substance",0,0,10000);Execute(f,ClassicExamples.Sources[5]);Check(!f.maze,"The shipped maze program reaches treasure on "+side+"x"+side);}
        f=Sandbox();session=Execute(f,"data=[1]\ndef worker():\n    data.append(99)\n    return len(data)\nd=spawn_drone(worker)\nvalue=wait_for(d)\nresult=(len(data)==1 and value==2)");Check(ScriptValue.Truth(session.drones[0].task.context.scope.values["result"]),"Worker isolation includes mutable collections");
        f=Sandbox();session=Execute(f,"handle=spawn_drone(harvest)\nif handle:\n    wait_for(handle)\nresult=has_finished(handle)");Check(ScriptValue.Truth(session.drones[0].task.context.scope.values["result"]),"Built-in functions can be spawned and handles are truthy");
        f=Sandbox();session=Execute(f,"result=(get_cost(Entities.Grass)=={})");Check(f.SeedCost("grass").Count==0&&f.Cost("grass",0).Count==1&&ScriptValue.Truth(session.drones[0].task.context.scope.values["result"]),"Planting and research costs use separate namespaces");
        f=Sandbox(1);f.Cell(0,0).entity="tree";f.Use("weird_substance",0,0);Check(f.Cell(0,0).infected,"A one-plot treatment flips its own state only once");
        f=Sandbox();session=Execute(f,"x=(0 < 2 < 3)\ny=(3 < 2 < 1)\nz=5 if x else 9\nresult=x and not y and z==5");Check(ScriptValue.Truth(session.drones[0].task.context.scope.values["result"]),"Chained comparison and conditional expressions");
        f=Sandbox();foreach(var c in f.Data.cells){c.entity="sunflower";c.growth=100;c.measure=10;}f.Cell(1,0).measure=15;f.Harvest(0,0);initial=f.Count("power");f.Harvest(1,0);Check(f.Count("power")-initial<8*Math.Pow(2,7),"A premature sunflower pick breaks the bonus sequence");
        f=Sandbox();string saved=UnityEngine.JsonUtility.ToJson(f.Data);var roundtrip=UnityEngine.JsonUtility.FromJson<ClassicSave>(saved);Check(roundtrip.cells.Count==f.Data.cells.Count&&roundtrip.records!=null&&roundtrip.personalBest!=null,"The fresh save format serializes its own economy and records");
        f=Sandbox();f.Cell(0,0).entity="bush";f.Use("weird_substance",0,0,10000);saved=UnityEngine.JsonUtility.ToJson(f.Data);var restored=new ClassicFarm{Data=UnityEngine.JsonUtility.FromJson<ClassicSave>(saved)};Check(restored.maze&&restored.walls.Length==16&&restored.treasure==f.treasure,"Maze walls and treasure survive save roundtrip");
        f=Sandbox();var paused=new ClassicSession(f);paused.Start("move(East)\nmove(North)");paused.Paused=true;paused.Step();Check(paused.Paused&&paused.drones[0].task.Steps==1,"Single step executes one pulse and keeps other work paused");
        f=Sandbox();f.Data.programs.Add(new ClassicProgram("trial","while num_items(Items.Hay)<1000:\n    for r in range(get_world_size()):\n        for c in range(get_world_size()):\n            if can_harvest():\n                harvest()\n            move(East)\n        move(North)"));session=Execute(f,"leaderboard_run(Leaderboards.Hay,'trial',64)");Check(f.Data.records.Count==1&&f.Data.records[0].seconds>0,"Local leaderboard API evaluates a separate program and records success");
        f=Sandbox(4);foreach(var c in f.Data.cells){c.entity="";c.ground="soil";}initial=f.Count("bone");Execute(f,ClassicExamples.Sources[8]);Check(f.Count("bone")>initial&&f.Data.harvested.Any(s=>s.id=="bone"),"Tail coverage ends safely and records its bone yield");
        f=Sandbox(4);foreach(var c in f.Data.cells){c.entity="";c.ground="soil";}session=Execute(f,"change_hat(Hats.Dinosaur_Hat)\nnext_target=measure()\nchange_hat(Hats.Straw_Hat)");var target=(object[])session.drones[0].task.context.scope.values["next_target"];Check(ScriptValue.Number(target[0])!=0||ScriptValue.Number(target[1])!=0,"Apple measurement reports the next apple position");
        f=Sandbox(8);Execute(f,"set_world_size(2)\nset_execution_speed(1)\nharvest()");Check(f.Data.size==8&&f.Data.defaultSize==0,"Temporary debug field size restores after execution");
        f=Sandbox(8);session=new ClassicSession(f);session.Start("set_world_size(2)\nprint(1/0)");for(int i=0;i<1000&&session.Running;i++)session.FixedTick();Check(session.Error!=""&&f.Data.size==8&&f.Data.defaultSize==0,"Failed debug programs restore the original field size");
        f=Sandbox(8);session=new ClassicSession(f);session.Start("set_world_size(2)\nharvest()");for(int i=0;i<1000&&session.Running;i++)session.Step();Check(!session.Running&&f.Data.size==8&&f.Data.defaultSize==0,"Stepping to completion restores the original field size");
        Directory.CreateDirectory("InternalTestReports/0.11.1");File.WriteAllText("InternalTestReports/0.11.1/classic.json",UnityEngine.JsonUtility.ToJson(new Report{passed=checks,checks=names.ToArray()},true));UnityEngine.Debug.Log("CLASSIC CHECKS PASSED: "+checks);
    }
    [Serializable] public class Report {public int passed;public string[] checks;}
}
